(function(){
 'use strict';
 const M=PlannerModel,D=PlannerData,key='viewdding.album.roadmap.v1';
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let state;try{state=M.clean(JSON.parse(localStorage.getItem(key)))}catch{state=M.clean(null)}
 let stage=D.stages.some(s=>s.id===state.focusStageId)?state.focusStageId:'start';
 let filters={stage:'all',category:'all',status:'open'},storageFailed=false;
 const categories=[...new Set(D.items.map(t=>t.category))];
 function surveyDone(){try{return !!SurveyModel.cleanPair(JSON.parse(localStorage.getItem('viewdding.album.survey.v1')))}catch{return false}}
 const all=()=>M.tasks(D,state,surveyDone());
 function persist(){try{localStorage.setItem(key,JSON.stringify(state));storageFailed=false}catch{storageFailed=true;toast('저장 공간을 사용할 수 없어 이번 방문 동안만 유지돼요.')}}
 const opts=(rows,value)=>rows.map(([v,l])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`).join('');
 const shortDate=v=>v?v.replaceAll('-','. '):'';
 function refresh(focusId){const x=window.scrollX,y=window.scrollY,rail=document.querySelector('.p-timeline'),railLeft=rail?.scrollLeft||0;render();const nextRail=document.querySelector('.p-timeline');if(nextRail)nextRail.scrollLeft=railLeft;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});window.scrollTo({left:x,top:y,behavior:'instant'})}
 function update(id,values){if(!all().some(t=>t.id===id))return;state.items[id]={...state.items[id],...values,updatedAt:new Date().toISOString()};persist()}
 function dateMarkup(){return `<div class="p-wedding-date">${icon('calendar')}<div><span>우리의 결혼식</span><strong>${state.weddingDate?shortDate(state.weddingDate):'날짜를 정해볼까요?'}</strong></div><button class="text-button" id="p-date-open" data-p-action="date">${state.weddingDate?'날짜 변경':'날짜 설정'}</button></div>`}
 function summary(){const s=M.stats(all());return `<section class="p-summary" aria-label="준비 요약"><div class="p-progress"><div><span>우리의 준비 기록</span><strong>${s.percent}<small>%</small></strong></div><progress value="${s.done}" max="${Math.max(1,s.active)}" aria-label="하지 않음을 제외한 완료율"></progress><p><b>${s.done}</b> / ${s.active}개 완료${s.skipped?' · 하지 않음 '+s.skipped+'개 제외':''}</p></div>${dateMarkup()}<div class="p-summary-note">${icon('check')}<p>로드맵과 나의 할 일이 연결돼요.<br> 어느 쪽에서 체크해도 함께 반영됩니다.</p></div></section>`}
 function toolHref(h){if(h.startsWith('/gatherings'))return h.includes('family_meeting')?'#family':'#invitation';if(h.startsWith('/favorites'))return '#scrap';return {'/search/':'#halls','/survey/':'#survey','/wedding-color/':'#color','/self-snap/':'#snap','/essentials/':'#essentials'}[h]||'#home'}
 function row(t,compact=false){return `<article class="p-task ${t.status==='done'?'is-done':''} ${t.status==='skipped'?'is-skipped':''}"><input class="p-check" id="p-check-${e(t.id)}" type="checkbox" data-p-check="${e(t.id)}" ${t.status==='done'?'checked':''} aria-label="${e(t.title)} 완료"><div class="p-task-main"><div class="p-task-meta"><span>${e(t.category)}</span>${compact?'':`<span>${e(t.timing)}</span>`}${t.importance==='optional'?'<span>선택 항목</span>':''}</div><label class="p-task-title" for="p-check-${e(t.id)}">${e(t.title)}</label>${compact?'':`<p>${e(t.description||'직접 추가한 준비 기록이에요.')}</p>`}<div class="p-task-bottom">${t.due?`<span class="p-date">${icon('calendar')}${shortDate(t.due)}<span>${t.explicitDue?'예정':'추천'}</span></span>`:'<span>예정일 미정</span>'}<span>${e(t.owner)}</span>${compact&&t.note?'<span>메모 있음</span>':''}${!compact?`${t.linkedTool?`<a href="${toolHref(t.linkedTool.href)}">${e(t.linkedTool.label)} ${icon('arrow')}</a>`:''}`:''}</div>${t.note&&!compact?`<div class="p-task-note">${e(t.note)}</div>`:''}</div><div class="p-task-actions"><span class="p-status p-status-${t.status}">${M.statuses[t.status]}</span><button class="text-button" id="p-edit-${e(t.id)}" data-p-edit="${e(t.id)}" aria-label="${e(t.title)} 일정과 메모 수정">일정 · 메모 ${icon('arrow')}</button></div></article>`}
 function footnote(){return `<p class="p-footnote">${storageFailed?'브라우저 저장을 사용할 수 없어 새로고침하면 이번 변경이 사라질 수 있어요.':'준비 기록은 이 브라우저에 자동 저장됩니다.'} 추천 시기는 참고용이며, 예약 상황에 맞게 바꿀 수 있어요.</p>`}
 function road(){const tasks=all(),current=D.stages.find(s=>s.id===stage),list=tasks.filter(t=>t.stage===stage),s=M.stats(list);return `${heading('','결혼 준비 로드맵','준비 시작부터 결혼 후까지, 시기별로 필요한 일을 살펴보세요.',`<a href="#checklist" class="outline-button">${icon('check')} 나의 할 일</a>`)}${summary()}<div class="p-road-layout"><nav class="p-timeline" aria-label="결혼 준비 시기">${D.stages.map((s,i)=>{const c=M.stats(tasks.filter(t=>t.stage===s.id));return `<button id="p-stage-${s.id}" data-p-stage="${s.id}" aria-pressed="${s.id===stage}"><span class="p-step">${String(i+1).padStart(2,'0')}</span><span><strong>${s.timing}</strong><small>${s.label}</small></span><span class="p-stage-count">${c.done}/${c.active}</span></button>`}).join('')}</nav><section class="p-stage-content"><header class="p-stage-heading"><div><span class="section-eyebrow">${current.timing}</span><h2>${current.label}</h2><p>${current.description}</p></div><span class="p-stage-total">${s.done} / ${s.active} 완료</span></header><div class="p-stage-links"><span>${state.weddingDate?`${shortDate(M.suggested(state.weddingDate,current))} 전후 추천`:'결혼식 날짜를 설정하면 추천 날짜를 볼 수 있어요.'}</span><button class="text-button" data-p-stage-tasks="${stage}">이 시기 할 일 모아보기 ${icon('arrow')}</button></div><div class="p-task-list">${list.map(t=>row(t)).join('')}</div></section></div>${footnote()}`}
 function checklist(){const tasks=all(),base=M.filter(tasks,{...filters,status:'all'}),list=M.filter(tasks,filters);const counts={all:base.length,open:base.filter(t=>['todo','doing'].includes(t.status)).length,...M.stats(base)};const tabs=[['open','남은 할 일'],['doing','진행 중'],['done','완료'],['all','전체'],['skipped','하지 않음']];return `${heading('','나의 할 일','일정과 진행 상태를 기록하고, 우리에게 필요한 준비만 챙기세요.',`<button id="p-add" class="solid-button" data-p-action="add">${icon('plus')} 할 일 추가</button>`)}${summary()}<section class="p-workspace"><div class="p-filters"><label>준비 시기<select id="p-filter-stage" data-p-filter="stage">${opts([['all','모든 시기'],...D.stages.map(s=>[s.id,s.timing+' · '+s.label])],filters.stage)}</select></label><label>준비 분야<select id="p-filter-category" data-p-filter="category">${opts([['all','모든 분야'],...categories.map(c=>[c,c])],filters.category)}</select></label><button class="text-button" data-p-action="reset">${icon('reset')} 초기화</button></div><div class="p-status-tabs" aria-label="할 일 상태">${tabs.map(([id,label])=>`<button id="p-status-${id}" data-p-status="${id}" aria-pressed="${filters.status===id}">${label}<span>${counts[id]}</span></button>`).join('')}</div><div class="p-list-heading"><h2>${tabs.find(([id])=>id===filters.status)[1]} <span>${list.length}</span></h2><span>준비 시기순</span></div>${list.length?D.stages.map(s=>{const items=list.filter(t=>t.stage===s.id);return items.length?`<section class="p-task-group"><h3>${s.timing}<span>${s.label}</span></h3><div class="p-task-list">${items.map(t=>row(t,true)).join('')}</div></section>`:''}).join(''):`<div class="p-empty">${icon('check')}<h3>이 조건의 할 일이 없어요.</h3><p>다른 시기나 상태를 선택해보세요.</p><button class="outline-button" data-p-action="reset">모든 할 일 보기</button></div>`}</section>${footnote()}`}
 function editTask(id){const t=all().find(t=>t.id===id);if(id&&!t)return;openDialog(`<span class="section-eyebrow">나의 준비 기록</span><h2>${t?'일정과 진행 상태':'할 일 추가'}</h2><form id="planner-task-form" class="p-form" data-task-id="${e(id||'')}"><label>할 일<input name="title" maxlength="100" required value="${e(t?.title||'')}" placeholder="예: 웨딩홀 투어 예약하기"></label>${t?.description?`<p class="p-form-help">${e(t.description)}</p>`:''}<div class="p-form-grid"><label>준비 시기<select name="stage">${opts(D.stages.map(s=>[s.id,s.timing]),t?.stage||(filters.stage!=='all'?filters.stage:stage))}</select></label><label>분야<select name="category">${opts(categories.map(c=>[c,c]),t?.category||'기본 계획')}</select></label><label>진행 상태<select name="status">${opts(Object.entries(M.statuses),t?.status||'todo')}</select></label><label>담당<select name="owner">${opts(['함께','나','파트너','가족'].map(c=>[c,c]),t?.owner||'함께')}</select></label></div><label>예정일 <span class="p-field-hint">비워두면 결혼식 기준 추천 날짜를 사용해요.</span><input type="date" name="due" value="${t?.explicitDue?t.due:''}" min="2000-01-01" max="2100-12-31"></label><label>메모<textarea name="note" rows="3" maxlength="1000" placeholder="예약 시간, 업체명, 상담할 내용 등을 남겨보세요.">${e(t?.note||'')}</textarea></label><div class="j-dialog-actions"><button type="button" class="outline-button" data-p-action="cancel">취소</button><button class="solid-button" type="submit">${t?'변경 저장':'할 일 추가'}</button></div></form>`)}
 function dateDialog(){openDialog(`<span class="section-eyebrow">OUR WEDDING DAY</span><h2>결혼식 날짜 설정</h2><p>날짜에 맞춰 시기별 추천 일정을 계산해요.<br>직접 지정한 할 일의 예정일은 그대로 유지됩니다.</p><form id="planner-date-form" class="p-form"><label>결혼식 날짜<input type="date" name="weddingDate" value="${state.weddingDate}" min="2000-01-01" max="2100-12-31"></label><p class="p-form-help">아직 미정이라면 비워두어도 괜찮아요.</p><div class="j-dialog-actions"><button type="button" class="outline-button" data-p-action="cancel">취소</button><button class="solid-button">저장</button></div></form>`)}
 function upcoming(){const list=M.upcoming(all()).slice(0,3);return list.length?list.map(t=>`<a class="p-upcoming" href="#checklist"><span><strong>${e(t.title)}</strong><small>${e(t.category)} · ${e(t.timing)}</small></span><span>${t.due?shortDate(t.due):'예정일 미정'}</span></a>`).join(''):'<p class="p-footnote">남은 준비가 없어요. 필요한 할 일을 추가해보세요.</p>'}
 function homeStats(){const s=M.stats(all());return `<span class="metric-label">완료한 할 일</span><span class="metric-value">${s.done}<small>/ ${s.active} 완료</small></span><div class="tiny-progress"><i style="width:${s.percent}%"></i></div>`}
 function homeDate(){const days=state.weddingDate?Math.ceil((new Date(state.weddingDate+'T00:00:00')-new Date(new Date().setHours(0,0,0,0)))/86400000):null;return `<span>결혼식</span><strong>${state.weddingDate?shortDate(state.weddingDate):'날짜 미정'}</strong><button class="text-button" data-p-action="date">${days===null?'날짜 설정':days>0?days+'일 남음':days===0?'오늘':'날짜 변경'}</button>`}
 document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.pStage){stage=d.pStage;state.focusStageId=stage;persist();refresh(el.id)}if(d.pStageTasks){filters.stage=d.pStageTasks;filters.category='all';filters.status='open';location.hash='checklist'}if(d.pStatus){filters.status=d.pStatus;refresh(el.id)}if(d.pEdit)editTask(d.pEdit);if(d.pAction==='add')editTask();if(d.pAction==='date')dateDialog();if(d.pAction==='cancel')dialog.close();if(d.pAction==='reset'){filters={stage:'all',category:'all',status:'all'};refresh('p-status-all')}});
 document.addEventListener('change',event=>{const el=event.target,d=el.dataset;if(d.pCheck){update(d.pCheck,{status:el.checked?'done':'todo'});refresh(el.id)}if(d.pFilter){filters[d.pFilter]=el.value;refresh(el.id)}});
 document.addEventListener('submit',event=>{const f=event.target;if(!['planner-task-form','planner-date-form'].includes(f.id))return;event.preventDefault();const fd=new FormData(f);if(f.id==='planner-date-form'){const date=String(fd.get('weddingDate')||'');if(date&&!M.validDate(date))return;state.weddingDate=date;persist();dialog.close();refresh('p-date-open');return}const title=String(fd.get('title')||'').trim();if(!title){toast('할 일을 입력해주세요.');return}let id=f.dataset.taskId;const values={title,stage:fd.get('stage'),category:fd.get('category'),status:fd.get('status'),owner:fd.get('owner'),due:fd.get('due')||'',note:String(fd.get('note')||'').trim()};if(!id){id='custom_'+crypto.randomUUID();state.custom.push({id,title,stage:values.stage,category:values.category});filters={stage:'all',category:'all',status:'open'}}update(id,values);dialog.close();refresh('p-edit-'+id);toast('준비 기록을 저장했어요.')});
 window.Planner={render:()=>page==='roadmap'?road():checklist(),all,homeStats,upcoming,homeDate,setCompletion:(ids,completed)=>{for(const id of ids)update(id,{status:completed?'done':'todo'});refresh()}};
})();
